Scripts.OnTextChanged:
if ( this:GetText() == "" ) then
	getglobal(this:GetParent():GetName() .. "OkayButton"):Disable();
	PallyPowerSaveMenuHelp:SetText(PALLYPOWER_TEXT_MUSTENTER); PallyPowerSaveMenuHelp:Show();
elseif ( PallyPower_SetExists(this:GetText()) ) then
	getglobal(this:GetParent():GetName() .. "OkayButton"):Enable();
	PallyPowerSaveMenuHelp:SetText(PALLYPOWER_TEXT_OVERWRITE); PallyPowerSaveMenuHelp:Show();
else
	getglobal(this:GetParent():GetName() .. "OkayButton"):Enable(); PallyPowerSaveMenuHelp:Hide();
end
